  9	package hotel.reservations;
 10	
 11	import hotel.rooms.Room;
 12	import java.math.BigDecimal;
 13	import java.math.RoundingMode;
 14	import java.time.LocalDate;
 15	import java.time.Month;
 16	
 17	/**
 18	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 19	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 20	 * (half-even) at every step.
 21	 */
 22	public final class PriceCalculator {
 23	
 24	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 25	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 26	
 27	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 28	        int nights = 0;
 29	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 30	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 31	            subtotal = subtotal.add(nightPrice(room, night));
 32	            nights++;
 33	        }
 34	        BigDecimal discount = switch (ratePlan) {
 35	            case STANDARD -> cents(BigDecimal.ZERO);
 36	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 37	        };
 38	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 39	    }
 40	
 41	    BigDecimal nightPrice(Room room, LocalDate night) {
 42	        BigDecimal nightlyRate = room.nightlyRate();
 43	        if (isHighSeason(night)) {
 44	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 45	        }
 46	        return cents(nightlyRate);
 47	    }
 48	
 49	    /** High season: from December 15 to the end of February, and the whole of July. */
 50	    static boolean isHighSeason(LocalDate date) {
 51	        Month month = date.getMonth();
 52	        return month == Month.JANUARY
 53	                || month == Month.FEBRUARY
 54	                || month == Month.JULY
 55	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
 56	    }
 57	
 58	    static BigDecimal cents(BigDecimal value) {
 59	        return value.setScale(2, RoundingMode.HALF_EVEN);
 60	    }
 61	}
 62	package hotel.reservations;
 63	
 64	import hotel.documents.ReservationReceipt;
 65	import hotel.messages.EmailSender;
 66	import hotel.rooms.Room;
 67	import hotel.rooms.Rooms;
 68	import java.math.BigDecimal;
 69	
 70	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 71	public final class ReservationService {
 72	
 73	    static final String HOTEL_NAME = "Pousada Maré Alta";
 74	
 75	    private final Rooms rooms;
 76	    private final ReservationStore store;
 77	    private final PriceCalculator priceCalculator;
 78	    private final EmailSender emailSender;
 79	
 80	    public ReservationService(
 81	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 82	        this.rooms = rooms;
 83	        this.store = store;
 84	        this.priceCalculator = priceCalculator;
 85	        this.emailSender = emailSender;
 86	    }
 87	
 88	    public synchronized Reservation create(NewReservation request) {
 89	        if (!request.checkOut().isAfter(request.checkIn())) {
 90	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 91	        }
 92	        if (request.guests() < 1) {
 93	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 94	        }
 95	        Room room = rooms.find(request.roomNumber())
 96	                .orElseThrow(() -> new HotelException(
 97	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 98	        if (request.guests() > room.capacity()) {
 99	            throw new HotelException(
100	                    ErrorCode.CAPACITY_EXCEEDED,
101	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
102	        }
103	        boolean roomTaken = store.all().stream()
104	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
105	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
106	        if (roomTaken) {
107	            throw new HotelException(
108	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
109	        }
110	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
111	        Reservation reservation = new Reservation(store.nextId(), request, price);
112	        store.save(reservation);
113	        return reservation;
114	    }
115	
116	    public Reservation find(long reservationId) {
117	        return store.find(reservationId)
118	                .orElseThrow(() -> new HotelException(
119	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
120	    }
121	
122	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
123	    public synchronized Reservation confirm(long reservationId) {
124	        Reservation reservation = find(reservationId);
125	        if (reservation.status() != ReservationStatus.PENDING) {
126	            throw notAllowed(reservation, "confirm");
127	        }
128	        reservation.confirmPayment();
129	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
130	        emailSender.send(
131	                reservation.guest().email(),
132	                "Reserva confirmada - " + HOTEL_NAME,
133	                confirmationEmailBody(reservation, receipt));
134	        return reservation;
135	    }
136	
137	    /**
138	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
139	     * reservation was never paid, so nothing comes back).
140	     */
141	    public synchronized Reservation cancel(long reservationId) {
142	        Reservation reservation = find(reservationId);
143	        if (reservation.status() != ReservationStatus.PENDING
144	                && reservation.status() != ReservationStatus.CONFIRMED) {
145	            throw notAllowed(reservation, "cancel");
146	        }
147	        BigDecimal refund = switch (reservation.ratePlan()) {
148	            case STANDARD -> reservation.amountPaid();
149	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
150	        };
151	        reservation.cancel(refund);
152	        return reservation;
153	    }
154	
155	    public synchronized Reservation checkIn(long reservationId) {
156	        Reservation reservation = find(reservationId);
157	        if (reservation.status() != ReservationStatus.CONFIRMED) {
158	            throw notAllowed(reservation, "check in");
159	        }
160	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
161	        return reservation;
162	    }
163	
164	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
165	    public synchronized ReservationReceipt checkOut(long reservationId) {
166	        Reservation reservation = find(reservationId);
167	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
168	            throw notAllowed(reservation, "check out");
169	        }
170	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
171	        return new ReservationReceipt(reservation, roomOf(reservation));
172	    }
173	
174	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
175	    public ReservationReceipt receiptCopy(long reservationId) {
176	        Reservation reservation = find(reservationId);
177	        if (!reservation.isPaid()) {
178	            throw notAllowed(reservation, "issue a receipt for");
179	        }
180	        return new ReservationReceipt(reservation, roomOf(reservation));
181	    }
182	
183	    private Room roomOf(Reservation reservation) {
184	        return rooms.find(reservation.roomNumber()).orElseThrow();
185	    }
186	
187	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
188	        return "Olá, " + reservation.guest().name() + "!\n\n"
189	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
190	                + receipt.text() + "\n"
191	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
192	                + "Até breve!\n";
193	    }
194	
195	    private static HotelException notAllowed(Reservation reservation, String operation) {
196	        return new HotelException(
197	                ErrorCode.OPERATION_NOT_ALLOWED,
198	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
199	    }
200	}
